import stylelint, { Rule } from "stylelint";

export const message =
  "Не используйте css переменные внутри универсального селектора. Это может привести к большому потреблению памяти";

export const ruleName = "plugin/css-property-memory";
const messages = stylelint.utils.ruleMessages(ruleName, {});
const meta = {
  url: "https://github.com/VKCOM/stylelint-config/tree/master/src/stylelint-css-property-memory",
};

const ruleFunction: Rule = () => {
  return (root, result) => {
    root.walkRules(/\*/, (node) => {
      node.walkDecls(/^--/, (node) => {
        stylelint.utils.report({
          ruleName,
          node,
          result,
          message,
        });
      });
    });
  };
};

ruleFunction.ruleName = ruleName;
ruleFunction.messages = messages;
ruleFunction.meta = meta;

export default stylelint.createPlugin(ruleName, ruleFunction);

function wrapString(value: string, wrap: string) {
  return wrap + value + wrap;
}

function wrapValue(value: string) {
  return wrapString(value, '`');
}

function messageReportBuilder(prop: string, logicalExample: string[]) {
  const logicalProps = logicalExample.map(wrapValue).join(', ');

  return `Физические значения свойства ${wrapValue(prop)} запрещены. Используйте логические свойства(${logicalProps})`;
}

export function messageReportSimple(prop: string) {
  const logicalProps = ['-block', '-inline'].map(suffix => prop + suffix);

  return messageReportBuilder(prop, logicalProps);
}

export function messageReportBorder(prop: string) {
  const logicalProps = ['-block-', '-inline-'].map(suffix => prop.replace('-', suffix));

  return messageReportBuilder(prop, logicalProps);
}

export function messageReportBorderRadius(prop: string) {
  const logicalProps = ['-start-start-', '-start-end-', '-end-end-', '-end-start-'].map(suffix =>
    prop.replace('-', suffix)
  );

  return messageReportBuilder(prop, logicalProps);
}

import path from 'path';
import { AtRule, Root, Rule } from 'postcss';
import { validateCustomProperties } from './lib/validate-custom-properties.js';
import { validateUtilities } from './lib/validate-utilities.js';
import { validateSelectors } from './lib/validate-selectors.js';
import { BemOptions, generateConfig } from './lib/generate-config.js';
import { toRegexp } from './lib/to-regexp.js';
import { isImplicitComponent, isImplicitUtilities } from './lib/check-implicit.js';
import stylelint, { PostcssResult } from 'stylelint';
import { ruleName } from './index.js';

export { BemOptions };

const DEFINE_VALUE = '([-_a-zA-Z0-9]+)\\s*(?:;\\s*(weak))?';
const DEFINE_DIRECTIVE = new RegExp(
  `(?:\\*?\\s*@define ${DEFINE_VALUE})|(?:\\s*postcss-bem-linter: define ${DEFINE_VALUE})\\s*`
);
const END_DIRECTIVE = new RegExp('(?:\\*\\s*@end\\s*)|' + '(?:\\s*postcss-bem-linter: end)\\s*');
const UTILITIES_IDENT = 'utilities';
const WEAK_IDENT = 'weak';

function stripUnderscore(str: string) {
  return str.replace(/^_/, '');
}

export function process(opts: BemOptions, root: Root, result: PostcssResult) {
  const config = generateConfig(opts);
  const patterns = config.patterns;

  type FileRange = {
    defined: string;
    start: number;
    weakMode: boolean;
    end?: number;
  };

  const ranges = findRanges(root);

  root.walkRules(rule => {
    if (rule.parent && (rule.parent as AtRule).name === 'keyframes') return;
    if (!rule.source) {
      return;
    }

    const ruleStartLine = rule.source?.start?.line;
    ranges.forEach(range => {
      if (ruleStartLine == null || ruleStartLine < range.start) {
        return;
      }
      if (range.end && ruleStartLine > range.end) {
        return;
      }
      checkRule(rule, range);
    });
  });

  function checkRule(rule: Rule, range: FileRange) {
    if (range.defined === UTILITIES_IDENT) {
      if (!patterns.utilitySelectors) {
        throw new Error('You tried to `@define utilities` but have not provided ' + 'a `utilitySelectors` pattern');
      }
      validateUtilities({
        rule,
        utilityPattern: toRegexp(patterns.utilitySelectors),
        ignorePattern: patterns.ignoreSelectors ? toRegexp(patterns.ignoreSelectors) : undefined,
        result,
      });
      return;
    }

    if (!patterns.componentSelectors) {
      throw new Error('You tried to `@define` a component but have not provided ' + 'a `componentSelectors` pattern');
    }

    validateCustomProperties({
      rule,
      componentName: range.defined,
      result,
      ignorePattern: patterns.ignoreCustomProperties ? toRegexp(patterns.ignoreCustomProperties) : undefined,
    });
    validateSelectors({
      rule,
      componentName: range.defined,
      weakMode: range.weakMode,
      selectorPattern: patterns.componentSelectors,
      selectorPatternOptions: config.presetOptions,
      ignorePattern: patterns.ignoreSelectors ? toRegexp(patterns.ignoreSelectors) : undefined,
      result,
    });
  }

  function findRanges(root: Root) {
    const ranges: FileRange[] = [];

    if (root.source && root.source.input && root.source.input.file) {
      const filename = root.source.input.file;
      if (isImplicitUtilities(config.implicitUtilities, filename)) {
        ranges.push({
          defined: 'utilities',
          start: 0,
          weakMode: false,
        });
      } else if (isImplicitComponent(config.implicitComponents, filename)) {
        let defined = stripUnderscore(path.basename(filename).split('.')[0]);
        if (defined === 'index') {
          defined = path.basename(path.join(filename, '..'));
        }

        if (defined !== UTILITIES_IDENT && !toRegexp(config.componentNamePattern).test(defined)) {
          stylelint.utils.report({
            ruleName,
            message: `Invalid component name from implicit conversion from filename ${filename}`,
            node: root,
            result: result as PostcssResult,
          });
        }

        ranges.push({
          defined,
          start: 0,
          weakMode: false,
        });
      }
    }

    root.walkComments(comment => {
      const commentStartLine = comment.source ? comment.source?.start?.line : null;
      if (!commentStartLine) return;

      if (END_DIRECTIVE.test(comment.text)) {
        endCurrentRange(commentStartLine);
        return;
      }

      const directiveMatch = comment.text.match(DEFINE_DIRECTIVE);
      if (!directiveMatch) return;
      const defined = (directiveMatch[1] || directiveMatch[3]).trim();
      if (defined !== UTILITIES_IDENT && !toRegexp(config.componentNamePattern).test(defined)) {
        stylelint.utils.report({
          ruleName,
          message: `Invalid component name in definition /*${comment}*/`,
          node: comment,
          result: result as PostcssResult,
        });
      }

      endCurrentRange(commentStartLine);
      ranges.push({
        defined,
        start: commentStartLine,
        weakMode: directiveMatch[2] === WEAK_IDENT,
      });
    });
    return ranges;

    function endCurrentRange(line: number) {
      const range = ranges[ranges.length - 1];
      if (!range || range.end) {
        return;
      }
      range.end = line;
    }
  }
}

import stylelint, { Rule } from 'stylelint';
import { process, BemOptions } from './process.js';
import { isRegExp } from './lib/utils.js';

function isString(object: any): boolean {
  return typeof object === 'string';
}

function isFunction(object: any): boolean {
  return typeof object === 'function';
}

function isStringOrRegExp(object: any): boolean {
  return isString(object) || isRegExp(object);
}

function isStringOrFunction(object: any): boolean {
  return isString(object) || isFunction(object);
}

function isBoolean(object: any): boolean {
  return typeof object === 'boolean';
}

const optionsSchema: any = {
  preset: ['suit', 'bem'],
  presetOptions: function () {
    return true;
  },
  componentName: [isStringOrRegExp],
  componentSelectors: [
    (pattern: any) => {
      if (isStringOrFunction(pattern)) return true;
      if (!pattern.initial) return false;
      if (!isStringOrFunction(pattern.initial)) return false;
      if (pattern.combined && !isStringOrFunction(pattern.combined)) return false;
      return true;
    },
  ],
  implicitComponents: [
    isBoolean,
    isString,
    function (pattern: any) {
      return Array.isArray(pattern) && pattern.every(isString);
    },
  ],
  implicitUtilities: [
    isBoolean,
    isString,
    function (pattern: any) {
      return Array.isArray(pattern) && pattern.every(isString);
    },
  ],
  utilitySelectors: [isStringOrRegExp],
  ignoreSelectors: [
    isStringOrRegExp,
    function (pattern: any) {
      if (!Array.isArray(pattern)) {
        return isStringOrRegExp(pattern);
      }
      return pattern.every(isStringOrRegExp);
    },
  ],
  ignoreCustomProperties: [
    isStringOrRegExp,
    function (pattern: any) {
      if (!Array.isArray(pattern)) {
        return isStringOrRegExp(pattern);
      }
      return pattern.every(isStringOrRegExp);
    },
  ],
};

export const ruleName = 'plugin/selector-bem-pattern';
const messages = stylelint.utils.ruleMessages(ruleName, {});

const ruleFunction: Rule<BemOptions> = primaryOption => {
  return (root, result) => {
    const isValid = stylelint.utils.validateOptions(result, ruleName, {
      actual: primaryOption,
      possible: optionsSchema,
    });

    if (!isValid) {
      return;
    }

    process(primaryOption, root, result);
  };
};

ruleFunction.ruleName = ruleName;
ruleFunction.messages = messages;

export default stylelint.createPlugin(ruleName, ruleFunction);

import stylelint, { Rule } from 'stylelint';

export const message =
  'Внутренняя реализация компонентов, включая их классы — не публичное API VKUI и может измениться в любой момент без предупреждения. Не привязывайтесь к ней, если хотите сохранить возможность без проблем обновляться на новые версии библиотеки.';

export const ruleName = 'plugin/vkui';
const messages = stylelint.utils.ruleMessages(ruleName, {});
const meta = {
  url: 'https://github.com/VKCOM/stylelint-config/tree/master/src/stylelint-vkui',
};

const ruleFunction: Rule = () => {
  return (root, result) => {
    root.walkRules(/\.vkui/, node => {
      stylelint.utils.report({
        ruleName,
        node,
        result,
        message,
      });
    });

    root.walkRules(/class[*~^$|]?=['"].*?vkui.*?['"]/, node => {
      stylelint.utils.report({
        ruleName,
        node,
        result,
        message,
      });
    });

    root.walkDecls(/^--vkui_internal/, node => {
      stylelint.utils.report({
        ruleName,
        node,
        result,
        message,
      });
    });

    root.walkDecls(node => {
      if (node.value.indexOf('--vkui_internal') > -1) {
        stylelint.utils.report({
          ruleName,
          node,
          result,
          message,
        });
      }
    });
  };
};

ruleFunction.ruleName = ruleName;
ruleFunction.messages = messages;
ruleFunction.meta = meta;

export default stylelint.createPlugin(ruleName, ruleFunction);
